import{at as e,it as t,n,vt as r}from"./chunks/framework.DdRMjwGS.js";var i=JSON.parse(`{"title":"AI 能力","description":"","frontmatter":{},"headers":[],"relativePath":"backend/ai.md","filePath":"backend/ai.md","lastUpdated":1794049926000}`),a={name:`backend/ai.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="ai-能力" tabindex="-1">AI 能力 <a class="header-anchor" href="#ai-能力" aria-label="Permalink to “AI 能力”">​</a></h1><p>本页说明 AI 模块的提供商、Provider 目录、提示词、知识库、助手、操作作为工具与模块开关，适用于接入或配置模型的后端与前端开发者。</p><p>AI 是 Tier 3 的可选模块（<code>BasicApp:Modules:AI:Enabled</code>，缺省开），架在框架的 AI 子系统（<code>AI.Abstractions</code>、<code>AI.OpenAI</code>、<code>AI.VectorData</code>）之上。四个页面都在「AI 中心」目录下：</p><table tabindex="0"><thead><tr><th>页面码</th><th>路由</th><th>菜单权限</th></tr></thead><tbody><tr><td><code>ai.providers</code></td><td><code>/ai/providers</code></td><td><code>ai.ai-providers.read</code></td></tr><tr><td><code>ai.assistants</code></td><td><code>/ai/assistants</code></td><td><code>ai.ai-assistants.read</code></td></tr><tr><td><code>ai.prompts</code></td><td><code>/ai/prompts</code></td><td><code>ai.ai-prompts.read</code></td></tr><tr><td><code>ai.knowledge-documents</code></td><td><code>/ai/knowledge-documents</code></td><td><code>ai.knowledge-documents.read</code></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title custom-block-title-default">TIP</p><p>本页说的是 BasicApp 自带的 AI 功能。用 AI 工具开发 BasicApp 见 <a href="./../ai/agents">For Agents</a>。</p></div><h2 id="提供商" tabindex="-1">提供商 <a class="header-anchor" href="#提供商" aria-label="Permalink to “提供商”">​</a></h2><p>模型提供商 <code>SysAiProvider</code> 是平台库实体、只在平台一侧：平台配置，租户经助手用到。协议只有 OpenAI 兼容一种，改端点即可接 DeepSeek、Azure OpenAI、Moonshot、自建的 vLLM 等。</p><table tabindex="0"><thead><tr><th>字段</th><th>规则</th></tr></thead><tbody><tr><td>编码</td><td>框架 Provider 名的文法：小写字母或数字开头，只有小写字母、数字与 <code>._-</code>，至多 64 个字符；唯一（部分唯一索引，删了可以重建），重复报 409 <code>AI_CONFLICT_101</code>；建后不可改</td></tr><tr><td>厂商</td><td>只用于分组展示（OpenAI、DeepSeek、Azure、Moonshot、自建、自定义，可自填），至多 50 个字符</td></tr><tr><td>聊天模型</td><td>必填</td></tr><tr><td>嵌入模型</td><td>为空即不能用于知识库。DeepSeek 没有嵌入接口，要另配一个带嵌入模型的提供商，助手在表单的「嵌入提供商」里指定它</td></tr><tr><td>端点</td><td>绝对的 http 或 https 地址。厂商是 OpenAI 时可留空，走它的官方端点；别的厂商必填（DeepSeek 填 <code>https://api.deepseek.com</code>），否则密钥会发给 OpenAI</td></tr><tr><td>API 密钥</td><td>经 <code>ISecretProtector</code> 加密存储，明文至多 1000 个字符；响应只给 <code>hasApiKey</code>。修改时留空即保留原密钥，但改了端点必须重新填写（<code>AI_VALIDATION_107</code>），旧密钥不会发往新地址</td></tr><tr><td>最大输出、温度</td><td>每次聊天调用带上（温度 0～2）</td></tr><tr><td>超时</td><td>1～3600 秒，为空即框架缺省的 100 秒；流式回复按每个增量计时</td></tr><tr><td>缺省</td><td>最多一个；助手与知识库没写提供商时用它。停用的不能设为缺省（<code>AI_CONFLICT_102</code>）</td></tr><tr><td>启停</td><td>一个状态；停用的不进 Provider 目录</td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>ai-providers.list</code> / <code>get</code></td><td><code>ai.ai-providers.read</code></td><td>列表可按状态、厂商与是否缺省筛选，按编码、名称与聊天模型搜索</td></tr><tr><td><code>ai-providers.create</code> / <code>update</code></td><td><code>ai.ai-providers.create</code> / <code>update</code></td><td>修改与启停交回读到的 <code>concurrencyStamp</code></td></tr><tr><td><code>ai-providers.set-status</code> / <code>set-default</code></td><td><code>ai.ai-providers.update</code></td><td>单条</td></tr><tr><td><code>ai-providers.delete</code></td><td><code>ai.ai-providers.delete</code></td><td>批量，逐项结果</td></tr><tr><td><code>ai-providers.test</code></td><td><code>ai.ai-providers.execute</code></td><td>测试连接，见下</td></tr></tbody></table><p>权限码都只在平台一侧，写操作进操作日志。</p><p>测试连接按当前配置临时建一次客户端（停用的也能测，用完即释放）：聊天模型发一句 <code>ping</code>（最大输出 16 个令牌），配了嵌入模型再嵌入一次并回报维度。连不通不是失败的调用，结果里写提供商给的原因；密钥解不开是 503 <code>AI_UNAVAILABLE_101</code>。</p><p>模型调用经出站地址策略（<code>XiHan:Security:Outbound</code>）：缺省只能连公网，本机或内网的模型端点要在那里放行，见<a href="./../configuration#xihan-security-outbound">配置参考</a>。</p><h2 id="provider-目录" tabindex="-1">Provider 目录 <a class="header-anchor" href="#provider-目录" aria-label="Permalink to “Provider 目录”">​</a></h2><p>框架的聊天、嵌入与知识库都经 <code>IAIProviderCatalog</code> 按名字解析客户端。BasicApp 以落库的 <code>AiProviderCatalog</code> 取代框架按配置建的目录，框架的 <code>XiHan:AI:Providers</code>、<code>DefaultProvider</code>、<code>DefaultEmbeddingProvider</code> 不生效，提供商在页面上维护：</p><ul><li>启用中的提供商按编码映射成框架的 Provider 配置，种类 <code>openai</code>；缺省提供商是标为缺省的那一个（只有一个时也不自动取它），聊天与嵌入共用这一个缺省。</li><li>框架的目录接口是同步的，所以目录持一份内存快照：宿主启动时装载，提供商写入的调用提交之后当场重载，新的调用即用新配置。</li><li>配了 Redis 时，写入的实例改写共享缓存的戳键 <code>ai:providers:stamp</code>，别的实例经共享缓存的变更通知重载；没配 Redis 即单实例。</li><li>重载只丢掉配置变了或没了的提供商缓存的客户端。解不开密钥的提供商记 Warning 后不进目录，按未配置处理，不当明文用。</li><li>目录以框架的 AI Provider 一致性套件自证（<code>AIProviderCatalogConformanceTests</code>）。</li></ul><p>没写提供商的编码时，聊天、嵌入与知识库都向目录要缺省提供商。<code>XiHan:AI:Knowledge:EmbeddingProvider</code> 不要配：写了它，没指定嵌入提供商的摄入与检索就固定用它，排在目录的缺省之前，缺省提供商改了也不跟着变。</p><h2 id="提示词" tabindex="-1">提示词 <a class="header-anchor" href="#提示词" aria-label="Permalink to “提示词”">​</a></h2><p>提示词 <code>SysAiPrompt</code> 是平台库实体、只在平台一侧：正文原样当助手的系统提示词，没有变量渲染，版本只是标签、同一编码只有一行。</p><table tabindex="0"><thead><tr><th>字段</th><th>规则</th></tr></thead><tbody><tr><td>编码</td><td>必填，至多 100 个字符；唯一（部分唯一索引，删了可以重建），重复报 409 <code>AI_CONFLICT_103</code>；建后不可改</td></tr><tr><td>名称</td><td>必填，至多 200 个字符</td></tr><tr><td>分类、版本</td><td>可选的标签，各至多 100 个字符</td></tr><tr><td>正文</td><td>必填，不限长度；列表不带正文，<code>ai-prompts.get</code> 才返回</td></tr><tr><td>启停</td><td>新建时选，之后走 <code>ai-prompts.set-status</code></td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>ai-prompts.list</code> / <code>get</code></td><td><code>ai.ai-prompts.read</code></td><td>列表可按状态与分类筛选，按编码与名称搜索</td></tr><tr><td><code>ai-prompts.create</code> / <code>update</code></td><td><code>ai.ai-prompts.create</code> / <code>update</code></td><td>修改与启停交回读到的 <code>concurrencyStamp</code></td></tr><tr><td><code>ai-prompts.set-status</code></td><td><code>ai.ai-prompts.update</code></td><td>单条</td></tr><tr><td><code>ai-prompts.delete</code></td><td><code>ai.ai-prompts.delete</code></td><td>批量，逐项结果</td></tr></tbody></table><p>提示词与提供商的必填文本都不接受纯空白（校验错误，消息键 <code>ai.fields.blank</code>）。</p><p>提示词还被助手引用时不能删除，逐项报 <code>AI_CONFLICT_107</code>。</p><h2 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to “知识库”">​</a></h2><p>知识文档 <code>SysKnowledgeDocument</code> 是租户库实体，平台与各租户各自维护、互不可见。向量也按侧分集合：平台 <code>knowledge.platform</code>，租户 <code>knowledge.&lt;租户 ID&gt;</code>；检索只在调用方一侧的集合里做，不靠元数据过滤。向量不在数据库里，库和向量库要一起备份与还原，见<a href="./../deployment#备份与还原">部署</a>。</p><table tabindex="0"><thead><tr><th>字段</th><th>规则</th></tr></thead><tbody><tr><td>标题</td><td>必填，至多 200 个字符</td></tr><tr><td>来源类型、来源标识</td><td>粘贴文本（<code>PasteText</code>）或上传文件（<code>UploadFile</code>）；上传的文件由前端读成文本提交，来源标识记文件名</td></tr><tr><td>原文</td><td>必填，只收文本，留在库里供重建</td></tr><tr><td>嵌入提供商</td><td>提供商的编码，为空即缺省提供商；写了但不存在或已停用报 400 <code>AI_VALIDATION_102</code></td></tr><tr><td>块数、状态、失败原因</td><td>状态是待索引（<code>Pending</code>）、已索引（<code>Indexed</code>）或失败（<code>Failed</code>）；失败时记错误码与发起人区域的文案，切不出块是 <code>AI_VALIDATION_103</code>。模型或向量库调用失败时原因只有异常类型，完整异常看应用日志</td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>knowledge-documents.list</code> / <code>get</code></td><td><code>ai.knowledge-documents.read</code></td><td>列表可按来源类型与状态筛选，按标题与来源搜索，不带原文</td></tr><tr><td><code>knowledge-documents.ingest</code></td><td><code>ai.knowledge-documents.create</code></td><td>请求内同步切块、嵌入并写入向量库</td></tr><tr><td><code>knowledge-documents.reindex</code></td><td><code>ai.knowledge-documents.update</code></td><td>用原文重建</td></tr><tr><td><code>knowledge-documents.delete</code></td><td><code>ai.knowledge-documents.delete</code></td><td>批量（1～100 个），逐项结果；连同向量一起删</td></tr><tr><td><code>knowledge-documents.query</code></td><td><code>ai.knowledge-documents.execute</code></td><td>知识问答，<code>GET</code>；问题至多 2000 个字符、条数 1～20，<code>answer</code> 为假只返回片段；<code>provider</code> 同时用于嵌入与聊天</td></tr><tr><td><code>knowledge-documents.search</code></td><td><code>ai.knowledge-documents.execute</code></td><td>只检索，<code>GET</code>；也发布为 MCP 与 AI 工具</td></tr></tbody></table><p>权限码两侧都有，写操作进操作日志。</p><ul><li><strong>事务</strong>：摄入与重建有网络 I/O，不放在调用的事务里。摄入先写一行待索引，索引之后再回写结果，两次写入各自提交；进程在途中中断即停在待索引，可以重建。回写失败时删掉刚写入的向量。</li><li><strong>索引失败不是失败的调用</strong>：没配向量库、模型不可达、维度不符时文档以失败状态保存并成功返回，原因记在文档上，修好之后重建。</li><li><strong>重建先写后删</strong>：新块写入成功之后才裁掉旧版本多出来的块；失败时旧块照常可检索，块数不变。</li><li><strong>删除</strong>：先删向量再软删行。向量库不可达时这一项失败、行不删；索引失败且块数为 0 的文档没写入过向量，不碰向量库，没配向量库也删得掉。</li><li><strong>问答</strong>：要答案且有命中时才调模型，用框架内置的增强模板，最大输出与温度取提供商的配置。片段在列表里的顺序就是答案里的引用编号：<code>[n]</code> 对应第 n 个片段。检索失败照框架的错误码返回，不退化成纯模型回答。</li></ul><p>向量库是 Qdrant，配置见<a href="./../configuration#basicapp-ai-qdrant">配置参考</a>：写了 <code>BasicApp:AI:Qdrant:Host</code> 才装知识库，健康检查多一项 <code>ai.vectordata.store</code>。不配即知识库不可用：摄入的文档以失败保存，问答与检索返回 503 <code>AI_UNAVAILABLE_002</code>，不悄悄退到内存。向量维度要与嵌入模型一致（<code>XiHan:AI:Knowledge:Dimensions</code>，缺省 1536），不一致报 <code>AI_VALIDATION_002</code>；检索条数与切块参数也在这一节，缺省 5 条、块 1000 个字符、重叠 100。</p><p>提供商还被知识文档或助手引用时不能删除，逐项报 <code>AI_CONFLICT_104</code>。文档可能在任何一侧，所以删除时要逐个租户查一遍，独立库的租户查它自己的库；哪一侧查不了，这次删除就失败（503 <code>AI_UNAVAILABLE_104</code>）。</p><h2 id="助手" tabindex="-1">助手 <a class="header-anchor" href="#助手" aria-label="Permalink to “助手”">​</a></h2><p>助手 <code>SysAiAssistant</code> 是平台库实体：只在平台一侧配置，平台与租户的聊天都用同一批助手。会话复用聊天，聊天里的操作见<a href="./chat#助手会话">在线聊天</a>。</p><table tabindex="0"><thead><tr><th>字段</th><th>规则</th></tr></thead><tbody><tr><td>编码</td><td>必填，至多 100 个字符、不含空白；唯一（部分唯一索引，删了可以重建），重复报 409 <code>AI_CONFLICT_105</code>；建后不可改</td></tr><tr><td>名称、简介、开场白、头像</td><td>名称必填；头像是图片地址，为空用首字母；开场白在新建会话时作为第一条助手消息，为空不发</td></tr><tr><td>提示词的编码</td><td>为空用内置的系统提示词（按调用方区域取）；写了须存在且启用，否则报 400 <code>AI_VALIDATION_105</code></td></tr><tr><td>聊天提供商、嵌入提供商的编码</td><td>为空用缺省提供商；写了须存在且启用，否则报 400 <code>AI_VALIDATION_104</code></td></tr><tr><td>是否检索知识库</td><td>缺省开，检索的片段数 1～20，缺省 5；没配向量库时表单给出提示，开着的助手回复会失败</td></tr><tr><td>带入上下文的历史消息条数</td><td>0～50，缺省 10；至少带上本轮提问</td></tr><tr><td>可用的工具</td><td>缺省不带；只能勾框架工具目录里的（<code>Expose.Ai</code> 的只读操作），否则报 400 <code>AI_VALIDATION_106</code></td></tr><tr><td>缺省</td><td>最多一个；新建会话时缺省选中它。停用的不能设为缺省（<code>AI_CONFLICT_106</code>）</td></tr><tr><td>启停</td><td>一个状态；停用的不再出现在聊天里，已有会话不能继续提问</td></tr></tbody></table><table tabindex="0"><thead><tr><th>操作</th><th>权限码</th><th>说明</th></tr></thead><tbody><tr><td><code>ai-assistants.list</code> / <code>get</code></td><td><code>ai.ai-assistants.read</code></td><td>列表可按状态与是否缺省筛选，按编码与名称搜索</td></tr><tr><td><code>ai-assistants.tools</code></td><td><code>ai.ai-assistants.read</code></td><td>可勾选的工具（说明按调用方区域）与有没有向量库</td></tr><tr><td><code>ai-assistants.create</code> / <code>update</code></td><td><code>ai.ai-assistants.create</code> / <code>update</code></td><td>修改与启停交回读到的 <code>concurrencyStamp</code></td></tr><tr><td><code>ai-assistants.set-status</code> / <code>set-default</code></td><td><code>ai.ai-assistants.update</code></td><td>单条</td></tr><tr><td><code>ai-assistants.delete</code></td><td><code>ai.ai-assistants.delete</code></td><td>批量，逐项结果；已有会话不删，但不能继续提问</td></tr></tbody></table><p>权限码都只在平台一侧，写操作进操作日志。</p><p>字段安全登记了提供商、提示词、助手（读、新建、修改、启停）与知识文档（读、摄入），规则由 Access 统一套用，见<a href="./data-permission">数据权限与字段安全</a>。</p><p>生成一次回复的流程（<code>IChatAssistants</code>，Contracts 定义，AI 实现，Chat 只认这个接口）：</p><ol><li>系统提示词：配了提示词用它的正文，引用的提示词后来停用或没了即回复失败（<code>AI_UNAVAILABLE_103</code>），不回落到内置的；没配用内置的。</li><li>历史：Chat 从库里取最近的提问与回复，不信前端传的。</li><li>检索增强：开了知识库时，在调用方一侧检索本轮提问，有命中才把提问换成增强后的（框架内置的模板，片段带编号）。检索失败回复失败，不退化成纯模型回答。</li><li>生成：带上助手勾选的工具，最大输出与温度取提供商的配置，流式产出。工具以调用方身份执行，权限与租户隔离照常判定；没有权限时模型收到拒绝，回复本身不失败。聊天页把助手回复按 Markdown 显示，图片语法只留成链接、不自动加载：回复内容受知识库片段与工具结果影响，自动加载的地址能把对话带到外部。</li></ol><p>不做用量统计。</p><h2 id="操作作为工具" tabindex="-1">操作作为工具 <a class="header-anchor" href="#操作作为工具" aria-label="Permalink to “操作作为工具”">​</a></h2><p>操作可以按 <code>Expose</code> 发布为 MCP 工具（<code>Expose.Mcp</code>）与框架 AI 工具（<code>Expose.Ai</code>）：</p><ul><li>发布的是只读目录类操作：<code>users.list</code> / <code>get</code>、<code>departments.get</code> / <code>tree</code>、<code>positions.list</code> / <code>get</code>、<code>memberships.list</code>、<code>permissions.list</code>、<code>dicts.list</code> / <code>get</code> / <code>options</code>、<code>dict-items.list</code> / <code>tree</code>，我的待办 <code>tasks.list</code>，以及知识检索 <code>knowledge-documents.search</code>；助手从这些工具里勾选。</li><li>工具说明取自操作的本地化 <code>.title</code> / <code>.description</code>，权限与租户隔离照常生效。</li><li>宿主映射了 <code>/mcp</code> 端点，MCP 客户端可以带用户令牌直接调用，见 <a href="./../ai/mcp">MCP Server</a>。</li></ul><p>工具名由操作 ID 推出（<code>-</code> 与 <code>.</code> 换成 <code>_</code>），超过 64 个字符时截成前 55 个字符加 <code>_</code> 与 8 位哈希；要改名用 <code>XiHan:AI:Tools</code> / <code>XiHan:Protocols:Mcp:Tools</code>（键为操作 ID）。新增 <code>Expose.Mcp</code> / <code>Expose.Ai</code> 的操作必须只读，并登记在 <code>OperationExposureTests</code>。</p><h2 id="模块开关" tabindex="-1">模块开关 <a class="header-anchor" href="#模块开关" aria-label="Permalink to “模块开关”">​</a></h2><p><code>BasicApp:Modules:AI:Enabled</code> 设为 <code>false</code> 时宿主不装配 AI 包与 OpenAI 兼容的 Provider：权限码与页面不下发、操作 404，也不装向量库连接器与知识库 Provider；<code>sys_ai_provider</code>、<code>sys_ai_prompt</code>、<code>sys_ai_assistant</code> 与 <code>sys_knowledge_document</code> 仍由正式库的基线脚本建出（开发库的 <code>InitTables</code> 只建装配了的包的表）。写成 <code>true</code> / <code>false</code> 以外的值启动即失败。框架的工具目录随 Full Profile 照常装配，<code>XiHan:AI</code> 节照常校验，其他操作的 MCP 工具不受影响。</p><p>聊天不依赖 AI：关掉之后聊天照常，聊天的三个助手操作返回 503 <code>CHAT_UNAVAILABLE_001</code>，前端首次展开「新建」菜单时据此隐藏助手入口。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to “下一步”">​</a></h2><ul><li><a href="./../ai/mcp">MCP Server</a> · <a href="./chat">在线聊天</a> · <a href="./realtime">实时推送</a> · <a href="./../configuration#basicapp-modules">配置参考</a></li></ul>`,48)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};